import copy
import re
import traceback

from ta_messaging.alias_factory import DYNAMIC_SOURCE_REGEXPS
from ta_messaging.testenv import DYNAMIC_SOURCE_SUFFIX
from ute_common_abstract_core import aliases_registry
from ta_messaging.message_observers import InfiniteCallbackObserver
from ta_messaging.message_manager import MessageManager
import threading
from six.moves import queue
from collections import namedtuple

from ute_common_abstract_core.exceptions import UnknownAlias

from ta_measurements.measurement_parser import MeasurementParserByReconfigurationOnly,\
    MeasurementParserByReconfigurationOnly5G
from ta_measurements.exceptions import NoEventRecorded, NoUeAliasInRegistry, NoMeasurementNumberConfiguredOnUe

message_type_and_callback = namedtuple(typename='message_type_and_its_callback', field_names='message_type callback')
ALLOWED_TECHNOLOGY = ['4G', '5G']
ALLOWED_PARSER_IMPLEMENTATION = ['MeasurementParserByReconfigurationOnly', 'MeasurementParserByReconfigurationOnly5G']


class Measurements(object):
    """
    Measurements manager implementation.
    """
    def __init__(self, ue_alias, technology='4G'):
        self._measurementParser = get_measurement_parser_impl(technology=technology)()
        self.owner = get_owner(ue_alias)
        self._required_observers = create_required_observers(self._measurementParser, self.owner)
        self.is_running = threading.Event()
        self._event_semaphore = threading.Semaphore(0)
        self._awaited_event = None
        self._timeout_timer = None
        self._is_timeout = False
        self._event_count = 0
        self._saved_event_count = 0
        self._started = threading.Semaphore(0)
        self._ended = threading.Semaphore(0)
        threading.Thread(target=self.start).start()
        self._started.acquire()

    def clear_collected_measurements(self):
        """
        Clears counter of collected measurements and removes history of collected measurements
        :return:
        """
        self._event_count = 0
        self._saved_event_count = 0
        self._measurementParser.clear_collected_measurements()

    def save_current_event_count(self):
        """
        Saves current event count
        """
        self._saved_event_count = self.total_event_count

    def get_saved_event_count(self):
        """
        Returns saved event count
        """
        return self._saved_event_count

    @property
    def total_event_count(self):
        """
        Returns currently registered event count
        :return:
        """
        return self._event_count

    def _wait_on_event(self, event_num):
        '''
        Wait on specified event num.
        :param event_num:
        :return:
        '''
        self._awaited_event = event_num
        self._event_semaphore.acquire()

    def _is_measurement_available(self, event_num):
        """

        :param occurence:
        :return:
        """
        return True if self._event_count >= int(event_num) else False

    def _on_timeout(self):
        self._is_timeout = True
        self._event_semaphore.release()
        self._awaited_event = None

    def wait_for_measurement(self, after_occurrence=None, timeout=60):
        '''
        Wait for measurement if not available. Return specified measurement occurence,
        on the last one if no occurence specified.
        :param after_occurrence:
        :param timeout:
        :return:
        '''
        after_occurrence = int(after_occurrence) if after_occurrence is not None else 1
        if self._is_measurement_available(event_num=after_occurrence) is False:
            self._timeout_timer = threading.Timer(int(timeout), self._on_timeout)
            self._timeout_timer.start()
            self._wait_on_event(after_occurrence)
            if self._is_timeout:
                raise NoEventRecorded('Event occurrence: {} has not been observed, current event number: {}'.format(
                    after_occurrence, self._event_count))
        else:
            print("Mesurement {} already available".format(after_occurrence))
        return self.get_measurement(occurrence=after_occurrence)

    def get_measurement(self, occurrence=None):
        '''
        Get measurements available at the moment of calling this function.
        :param occurrence:
        :return:
        '''
        if occurrence == 'all':
            return self._measurementParser.measurements[:]
        else:
            occurrence = int(occurrence) if occurrence is not None else 0
            if occurrence > self.total_event_count:
                raise NoMeasurementNumberConfiguredOnUe('Requested occurrence :{} did not occur, '
                                                        'current event count: {}'
                                                        .format(occurrence, self.total_event_count))
            occurrence -= 1     # history list is numbered 0...n, measurements are numbered 1.. n+1
            return self._measurementParser.measurements[occurrence]

    def stop(self):
        """
        Stops observers threads.
        """
        if self.is_running.is_set():
            self.is_running.clear()
            self._end_observers()
            self._ended.acquire()

    def _end_observers(self):
        for observer in self._required_observers:
            observer.stop()

    def _rise_semaphore_if_event_expected(self):
        if self._awaited_event is not None:
            if self._event_count < self._awaited_event:
                return
            else:
                if self._timeout_timer.is_alive() is True:
                    self._timeout_timer.cancel()
                    self._event_semaphore.release()
                    self._awaited_event = None

    def _log_event(self):
        self._event_count = self._measurementParser.counted_events
        print("New event arrived, new total event count: {}".format(self._event_count))

    def start(self):
        '''
        Gets current received even number from queue and rises semaphore if needed.
        :return:
        '''
        self.is_running.set()
        self._started.release()
        while self.is_running.is_set():
            try:
                self._measurementParser.notify_queue.get(timeout=0.1)
            except queue.Empty:
                self._rise_semaphore_if_event_expected()
                # in case race condition between subscribing and receiving event
                continue
            self._log_event()
            self._rise_semaphore_if_event_expected()
        self._ended.release()


def get_owner(ue_alias):
    '''
    Returns onwer class.
    :param ue_alias:
    :return:
    '''
    alias_for_ue_identification = ue_alias + "__identification"
    if alias_for_ue_identification not in aliases_registry.aliases_registry():
        try:
            network_element = create_dynamic_ne(device=ue_alias)
            if network_element is None:
                raise UnknownAlias(
                    'Alias: {} not created and not found among dynamic message sources'.format(ue_alias))
            aliases_registry.aliases_registry()[alias_for_ue_identification] = network_element
        except Exception:
            traceback.print_exc()
            raise NoUeAliasInRegistry('Alias: {} does not exist. Consider setting it up first using ta_messaging '
                                      'or use dynamic source.'
                                      'Create Ue Alias robot keyword'
                                      .format(ue_alias))
    return aliases_registry.aliases_registry()[alias_for_ue_identification].network_elem_identifier

# below is hard-copy from ta_messaging.message_flow, refactoring is needed to have one common implementation


def get_running_dynamic_sources():
    dynamic_sources = []
    for src in list(aliases_registry.aliases_registry().values()):
        if hasattr(src, 'network_elem_identifier') and hasattr(src.network_elem_identifier, 'specific_for_tool') \
                and src.network_elem_identifier.specific_for_tool is not None:
            if DYNAMIC_SOURCE_SUFFIX in src.network_elem_identifier.specific_for_tool:
                dynamic_sources.append(src)
    return dynamic_sources


def get_types_of_running_dynamic_sources():
    return [src.network_elem_identifier.network_elem_type for src in get_running_dynamic_sources()]


def filter_dynamic_src_regexp_with_running_sources():
    regexpes = {}
    started_dynamic_types = get_types_of_running_dynamic_sources()
    for reg in list(DYNAMIC_SOURCE_REGEXPS.keys()):
        if reg in started_dynamic_types:
            regexpes[reg] = DYNAMIC_SOURCE_REGEXPS[reg]
    return regexpes


def get_dynamic_source_identification(device):
    matches_idents = []
    dynamic_regexpes = filter_dynamic_src_regexp_with_running_sources()
    for ident in list(dynamic_regexpes.keys()):
        if DYNAMIC_SOURCE_REGEXPS[ident].search(device):
            matches_idents.append(ident)
    assert len(matches_idents) < 2, 'Used alias: {} matches both UE (e.g. MY_UE_1) and CELL (e.g. MY_CELL_2_3),\
     do not use _NUMBER notation in global alias declaration'
    if len(matches_idents) == 1:
        dynamic_source_name = DYNAMIC_SOURCE_REGEXPS[matches_idents[0]].sub(r'\1', device)
        alias_of_source = dynamic_source_name + "__identification"
        dynamic_source = aliases_registry.aliases_registry()[alias_of_source] \
            if alias_of_source in aliases_registry.aliases_registry() else None
    else:
        dynamic_source = None
    return dynamic_source


def remove_dynamic_source_suffix(tool_specific_id):
    return re.sub(DYNAMIC_SOURCE_SUFFIX, '', tool_specific_id)


def exctract_id_from_dynamic_source_alias(identification, device):
    if identification.network_elem_type == 'UE':
        regexp = DYNAMIC_SOURCE_REGEXPS['UE']
        res = regexp.search(device)
        if res:
            return int(res.group(2))  # from MY_UE_1 returns '1', first group used for matching last name character
    else:
        raise UnknownAlias('Cannot extract ids for dynamic alias: {}:{}'.format(type(identification), identification))


def create_dynamic_ne(device):
    dynamic_source = get_dynamic_source_identification(device)
    if dynamic_source is not None:
        print('Matched dynamic source : {} for alias: {}'.format(dynamic_source, device))
        old_id_type = dynamic_source.network_elem_identifier.specific_for_tool
        new_id_type = remove_dynamic_source_suffix(old_id_type)
        new_id = exctract_id_from_dynamic_source_alias(dynamic_source.network_elem_identifier, device)
        new_dynamic_source_with_id = copy.deepcopy(dynamic_source)
        del new_dynamic_source_with_id.network_elem_identifier[old_id_type]
        new_dynamic_source_with_id.network_elem_identifier[new_id_type] = new_id
        new_dynamic_source_with_id.network_elem_identifier['alias'] = device
        new_dynamic_source_with_id.network_elem_identifier.specific_for_tool = new_id_type
        print('Creating dynamic identification :{} for alias: {}'.format(new_dynamic_source_with_id, device))
        network_element = new_dynamic_source_with_id
    else:
        network_element = None
    return network_element


def get_measurement_parser_impl(technology='4G'):
    '''
    Returns used parser implementation
    :return:
    '''
    if technology == '4G':
        return MeasurementParserByReconfigurationOnly
    elif technology == '5G':
        return MeasurementParserByReconfigurationOnly5G
    else:
        raise Exception('Technology: {} not supported, allowed values: {}'.format(technology, ALLOWED_TECHNOLOGY))


def create_required_observers(measurement_parser_impl_instance, owner):
    '''
    Creates requires observers for given measurement parser implementation and given owner.
    :param measurement_parser_impl_instance:
    :param owner:
    :return:
    '''
    message_type_and_callback_list = []
    observers = []
    parser_impl = measurement_parser_impl_instance.__class__.__name__
    assert parser_impl in ALLOWED_PARSER_IMPLEMENTATION,\
        'only {} supported'.format(ALLOWED_PARSER_IMPLEMENTATION)
    if parser_impl == 'MeasurementParserByReconfigurationOnly':
        message_type_and_callback_list.append(message_type_and_callback('RRCConnectionReconfiguration', 'process_measurement'))
    elif parser_impl == 'MeasurementParserByReconfigurationOnly5G':
        message_type_and_callback_list.append(
            message_type_and_callback('RRCReconfiguration', 'process_measurement'))
    for item in message_type_and_callback_list:
        callback = getattr(measurement_parser_impl_instance, item.callback)
        msg_type = item.message_type
        observer = InfiniteCallbackObserver(MessageManager()._dispatcher, msg_type, owner, callback)
        observers.append(observer)
    return observers
